def md(v): return '%d-%d' % v if v else None
def main():
    sk = pre_rows(get('sakura003_07.html')); sm = pre_rows(get('sakura004_07.html')); ka = phn_rows(get('phn_014.html')); ic = phn_rows(get('phn_012.html'))
    out = {}
    for n, (la, lo) in ST.items():
        a, b, c, d = sk.get(n, {}), sm.get(n, {}), ka.get(n, {}), ic.get(n, {})
        if not (a or c or d): continue
        out[n] = [la, lo, md(a.get('y2026')), md(a.get('normal')), md(b.get('y2026')), md(b.get('normal')), md(c.get('y2026')), md(c.get('normal')), md(d.get('y2026')), md(d.get('normal'))]
    here = os.path.dirname(os.path.abspath(__file__)); p = os.path.join(here, '..', 'data', 'season.json')
    json.dump({'updated': datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=9))).isoformat(timespec='minutes'), 'year': 2026,
               'cols': ['la', 'lo', 'sakura_kaika', 'sakura_kaika_normal', 'sakura_mankai', 'sakura_mankai_normal', 'kaede', 'kaede_normal', 'icho', 'icho_normal'], 'st': out},
              open(p, 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
    print('stations', len(out), '->', p)
if __name__ == '__main__': main()
